	gv, ok := attnVariantFor(g.gathRung())
	if ok {
		hpw = g.gathHeadsPerWG()
		gath = gathPipe(gv, g.gathGroups(), hpw)
		if _, ok := g.pipes[gath]; !ok {
			gath, hpw = "", 1
		} else {
			av = gv
			qBlocks = uint32(roundUpInt(g.rows, av.rows) / av.rows)
