	gb := base
	gb.ResOff = g.aGath
	gTiles := uint32(roundUpInt(g.rows, gathBM) / gathBM)
	add("gather", "attn.gather", gTiles, 1, gb)
	add("gathmask", "attn.gathmask", gTiles, 1, gb)
}

